mapper.select:
SELECT * FROM ( SELECT user_id, email, name, nickname, age, role, grade, gender, disease, disability, medication, profile_img, created_at, updated_at, deleted_at, ROW_NUMBER() OVER (ORDER BY created_at DESC) as rn FROM users WHERE deleted_at IS NULL
AND (nickname LIKE '%' || #{search} || '%' OR name LIKE '%' || #{search} || '%' OR email LIKE '%' || #{search} || '%')
) WHERE rn BETWEEN #{offset} + 1 AND #{offset} + #{pageSize}

SELECT * FROM ( SELECT user_id, email, name, nickname, age, role, grade, gender, disease, disability, medication, profile_img, created_at, updated_at, deleted_at, ROW_NUMBER() OVER (ORDER BY deleted_at DESC) as rn FROM users WHERE deleted_at IS NOT NULL
AND (nickname LIKE '%' || #{search} || '%' OR name LIKE '%' || #{search} || '%' OR email LIKE '%' || #{search} || '%')
) WHERE rn BETWEEN #{offset} + 1 AND #{offset} + #{pageSize}

SELECT COUNT(*)
FROM users
WHERE nickname = #{nickname}
AND deleted_at IS NULL

    AND user_id != #{excludeUserId}
